Listing 11.3 Font::RenderText Implementation
Texture* Font::RenderText(const std::string& text,
const Vector3& color, int pointSize)
{
Texture* texture = nullptr;
// Convert to SDL_Color
SDL_Color sdlColor;
sdlColor.r = static_cast<Uint8>(color.x * 255);
sdlColor.g = static_cast<Uint8>(color.y * 255);
sdlColor.b = static_cast<Uint8>(color.z * 255);
sdlColor.a = 255;
// Find the font data for this point size
auto iter = mFontData.find(pointSize);
if (iter != mFontData.end())
{
TTF_Font* font = iter->second;
// Draw this to a surface (blended for alpha)
SDL_Surface* surf = TTF_RenderText_Blended(font, text.c_str(),
sdlColor);
if (surf != nullptr)
{
// Convert from surface to texture
texture = new Texture();
texture->CreateFromSurface(surf);
SDL_FreeSurface(surf);
}
}
else
{
SDL_Log("Point size %d is unsupported", pointSize);
}
return texture;
}
Because creating a texture is somewhat expensive, the UI code does not call RenderText
every frame. Instead, it calls RenderText only when the text string changes and saves the
resulting texture. Then on every frame, the UI code can draw the texture that contains the
rendered text. For maximum efficiency, you could even render each letter in the alphabet to
separate textures and then stich these letter textures together to form words.
